package com.texto.emailplatform.campaign.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="campaign_schedules") public class CampaignScheduleEntity { @Id private UUID id; @Column(name="campaign_id",nullable=false) private UUID campaignId; @Column(name="tenant_id",nullable=false) private UUID tenantId; @Column(name="scheduled_at",nullable=false) private Instant scheduledAt; @Column(nullable=false) private String timezone; @Column(nullable=false) private String status; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt; @Column(name="invalidated_at") private Instant invalidatedAt;
public static CampaignScheduleEntity active(UUID campaignId,UUID tenantId,Instant at,String timezone){CampaignScheduleEntity s=new CampaignScheduleEntity();s.id=UUID.randomUUID();s.campaignId=campaignId;s.tenantId=tenantId;s.scheduledAt=at;s.timezone=timezone;s.status="ACTIVE";s.createdAt=s.updatedAt=Instant.now();return s;}public void invalidate(){status="INVALIDATED";invalidatedAt=updatedAt=Instant.now();}}
